(* Single i18n surface: en.edn-keyed lookups (t/tf/t1) and formatters.
   Resolve labels when constructing views, after the selected dictionary
   loads; module-level translated values retain the startup fallback.

   Dicts: en ships embedded in the bundle (Dicts_gen.en, generated by
   tools/dict_gen.ml from resources/dicts/*.edn). Every other locale
   loads on demand: Dicts_gen.dict_files maps locale -> edn filename,
   Web fetches lazy chunks and native reads bundled resource files.
   The table is built at runtime with the same Edn reader (see load/init below — main.ml
   awaits init before first render so a non-English boot never flashes
   English). Language follows the cljs :preferred-language signal —
   localStorage["preferred-language"] holds an EDN-quoted locale name
   (same read as Boot's document.lang wiring).

   Lookup order for `t key`:
   - non-English: loaded locale dict -> English path below (a missing
     locale dict behaves like a missing key — English, matching cljs
     tongue's :en fallback)
   - English: `en_overrides` (shipped text that deliberately differs
     from en.edn, e.g. casing kept for e2e/parity) -> en dict -> key.
   fn-valued cljs dict entries (plural/rich) are skipped by the
   generator; their OCaml call sites keep literal fns below. *)

open Promise_ext

(* substring search helpers (case-sensitive contains, case-insensitive
   contains/index) shared by popups, menus, icon picker, plugin list *)

let contains hay needle =
  let lh = String.length hay and ln = String.length needle in
  let rec go i = i + ln <= lh && (String.sub hay i ln = needle || go (i + 1)) in
  ln = 0 || go 0

let contains_ci hay needle =
  let h = String.lowercase_ascii hay and n = String.lowercase_ascii needle in
  contains h n

let index_ci hay needle =
  let h = String.lowercase_ascii hay and n = String.lowercase_ascii needle in
  let ln = String.length n and lh = String.length h in
  let rec go i =
    if ln = 0 || i + ln > lh then None
    else if String.sub h i ln = n then Some i
    else go (i + 1)
  in
  go 0

(* "{1}" / "{2}" placeholder substitution *)
let replace_all s pat rep =
  let plen = String.length pat in
  let b = Buffer.create (String.length s) in
  let i = ref 0 in
  while !i <= String.length s - plen do
    if String.sub s !i plen = pat then (
      Buffer.add_string b rep;
      i := !i + plen)
    else (
      Buffer.add_char b (String.get s !i);
      incr i)
  done;
  Buffer.add_string b (String.sub s !i (String.length s - !i));
  Buffer.contents b

(* positional substitution on a literal template *)
let sub s args =
  List.fold_left
    (fun (acc, i) a ->
      (replace_all acc ("{" ^ string_of_int i ^ "}") a, i + 1))
    (s, 1) args
  |> fst

(* The selected locale is an EDN-quoted storage value shared by both hosts. *)
let current_lang () =
  match Platform.local_storage_get "preferred-language" with
  | Some v -> Ui_services.storage_unquote v
  | None -> "en"

(* The generated English dictionary contains UTF-8 byte strings. Decode
   that data once at import; ordinary UI source uses {js|...|js} literals
   and runtime strings already use the host's text representation. *)
let tbl_of arr =
  let h = Hashtbl.create (Array.length arr) in
  Array.iter (fun (k, v) -> Hashtbl.replace h k (Platform.decode_utf8_bytes v)) arr;
  h

let en_tbl = lazy (tbl_of Dicts_gen.en)

(* Dictionaries are loaded on demand through each platform. Unknown
   locales retain English; missing keys fall back to the English table.
   File, fetch and parse failures propagate rather than hiding an invalid
   application distribution behind untranslated UI. *)

let locale_tbls : (string, (string, string) Hashtbl.t option) Hashtbl.t =
  Hashtbl.create 8

let locale_loads : (string, unit Js.Promise.t) Hashtbl.t = Hashtbl.create 4

let locale_tbl loc = Option.join (Hashtbl.find_opt locale_tbls loc)

(* Fetched dictionaries already contain decoded text. Keep keyword/string
   pairs, applying the same filter as dict_gen without another decode. *)
let tbl_of_text file text =
  match Edn.parse text with
  | Wire.Map kvs ->
      let h = Hashtbl.create (List.length kvs) in
      List.iter
        (fun (k, v) ->
          match (k, v) with
          | Wire.Keyword k, Wire.String v -> Hashtbl.replace h k v
          | _ -> ())
        kvs;
      h
  | _ -> failwith ("malformed i18n dict " ^ file)

let load loc : unit Js.Promise.t =
  match (Hashtbl.find_opt locale_loads loc, Hashtbl.find_opt locale_tbls loc) with
  | Some p, _ -> p
  | None, Some _ -> Js.Promise.resolve ()
  | None, None -> (
      match List.assoc_opt loc Dicts_gen.dict_files with
      | None ->
          Hashtbl.replace locale_tbls loc None;
          Js.Promise.resolve ()
      | Some file ->
          let p =
            let* text = Platform.load_dict_file file in
            Hashtbl.replace locale_tbls loc (Some (tbl_of_text file text));
            Js.Promise.resolve ()
          in
          Hashtbl.replace locale_loads loc p;
          p)

(* Boot waits for the selected dictionary before constructing views. *)
let init () = load (current_lang ())

